void clDNStartDino::Update() {
    Vec3f local;
    Vec3f eye9;
    Vec3f eye;
    if (gate == 0 || fire == 0) {
        return;
    }
    {
    if (!IsRaceStarted()) {
        hideGate = 0;
        hideFire = 1;
        Animate();
        return;
    }
    hideFire = 1;
    hideGate = 1;
    if (g_cupId >= 9) {
        CObj_LoadProjMatrix(GetCourseScene3D(), &eye9);
        float z = eye9.z;
        hideGate = 0;
        hideFire = 0;
        if (z >= lbl_806DB544) {
            if (jointSet != 0) {
                fireL = ResolveJointByName(gate, lbl_803DA1B0);
                fireR = ResolveJointByName(gate, lbl_803DA1C4);
            }
        } else if (jointSet != 1) {
            fireL = ResolveJointByName(gate, lbl_803DA1D8);
            fireR = ResolveJointByName(gate, lbl_803DA1EC);
        }
    } else {
        CObj_LoadProjMatrix(GetCourseScene3D(), &eye);
        if (eye.x >= lbl_803DA13C[0] && eye.x <= lbl_803DA13C[2]) {
            if (eye.z >= lbl_803DA13C[1] && eye.z <= lbl_803DA13C[3]) {
                hideFire = 0;
            }
            if (eye.z >= lbl_803DA12C[1] && eye.z <= lbl_803DA12C[3]) {
                hideGate = 0;
            }
        }
    }
    if (g_gameMode == 2) {
        Animate();
        return;
    }
    if (hideFire == 0) {
        if (fireOn == 0) {
            fireOn = 1;
            hinoko->active = 1;
        }
    } else if (fireOn != 0) {
        fn_8016C394(0x34);
        fireOn = 0;
        hinoko->active = 0;
    }
    if (timer < 0) {
        fn_8016C394(0x34);
        fireOn = 0;
        hinoko->active = 0;
    }
    if (fireOn == 1) {
        local.x = DNStartDino_tail_data_806D05D0;
        local.y = DNStartDino_tail_data_806D05D4;
        local.z = DNStartDino_tail_data_806D05D8;
        float (*mm)[4] = JObjGetMtx(fireL);
        PSMTXMultVecSR(mm, &local, &fireDir[0]);
        firePos[0].x = mm[0][3];
        firePos[0].y = mm[1][3];
        firePos[0].z = mm[2][3];
        mm = JObjGetMtx(fireR);
        PSMTXMultVecSR(mm, &local, &fireDir[1]);
        firePos[1].x = mm[0][3];
        firePos[1].y = mm[1][3];
        firePos[1].z = mm[2][3];
        fn_8016C288(0x34, firePos);
        hinoko->SetPos(firePos);
        hinoko->SetDir(fireDir);
    }
    int nfree = 0;
    for (int i = 0; i < 20; i++) {
        if (!puffs[i].active) {
            if (nfree < 2) {
                freePuffs[nfree++] = &puffs[i];
            }
        } else {
            FirePuff *p = &puffs[i];
            p->pos.x = p->vel.x * p->speed + p->pos.x;
            p->pos.y = p->vel.y * p->speed + p->pos.y;
            p->pos.z = p->vel.z * p->speed + p->pos.z;
            p->scale += p->dscale;
            p->vel.y += p->lift;
            p->speed -= lbl_806DB514;
            p->alpha -= p->fade;
            p->dscale *= lbl_806DB548;
            if (p->alpha <= lbl_806DB524) {
                p->active = 0;
            }
        }
    }
    if (hideFire == 0) {
        if (cooldown == 0 && fireOn == 1) {
            SpawnFire();
        }
        if (++timer > 180) {
            f1C = lbl_806DB524;
            timer = -125;
        }
        Animate();
    } else {
        if (timer < 0) {
            timer++;
        }
        if (timer > 0) {
            if (++timer > 180) {
                timer = 0;
            }
        }
    }
    if (cooldown != 0) {
        cooldown--;
    }
    hinoko->Update();
    }
}
